s=s.replace("var currentName = null, currentAvatar = null, panelMode = null, replyTimer = null;", "var currentName = null, currentAvatar = null, panelMode = null, replyTimer = null;\n  var messageQuoteDraft = null;\n  var forwardMessageIndex = -1;", 1)
# selection helpers
