c=c.replace('''.pm-message-action-item{\n  min-width:58px; padding:7px 8px 6px; border:0; border-radius:10px;''','''.pm-message-action-item{\n  min-width:0; padding:7px 6px 6px; border:0; border-radius:10px;''',1)
anchor='.pm-message-action-popover .pm-message-action-item[data-message-action="transcribe"] .pm-message-action-icon svg{ width:24px; height:24px; }\n'
addon='''\n.pm-quote-bar{ display:none; flex:none; align-items:center; gap:8px; margin:0 12px; padding:8px 10px; border-left:3px solid var(--fg); border-radius:8px; background:rgba(127,127,127,.10); box-sizing:border-box; color:var(--fg); }\n.pm-quote-bar.is-open{ display:flex; }\n.pm-quote-main{ min-width:0; flex:1; }\n.pm-quote-label{ font-size:10px; line-height:1.15; margin-bottom:2px; opacity:.62; }\n.pm-quote-text{ font-size:12px; line-height:1.35; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }\n.pm-quote-cancel{ flex:none; width:28px; height:28px; border:0; padding:0; display:grid; place-items:center; border-radius:50%; background:transparent; color:currentColor; font-size:21px; line-height:1; }\n.pm-quote-cancel:active{ background:rgba(127,127,127,.14); }\n.pm-bubble-quote{ margin:-1px 0 6px; padding:5px 7px; border-left:2px solid currentColor; border-radius:2px; background:rgba(127,127,127,.12); opacity:.84; }\n.pm-bubble-quote-author{ font-size:10px; line-height:1.2; margin-bottom:2px; opacity:.78; }\n.pm-bubble-quote-text{ font-size:11px; line-height:1.3; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }\n.pm-forward-sheet{ position:fixed; inset:0; z-index:240; display:none; align-items:flex-end; justify-content:center; padding:0 12px calc(12px + env(safe-area-inset-bottom,0px)); box-sizing:border-box; background:rgba(0,0,0,.28); backdrop-filter:blur(3px); -webkit-backdrop-filter:blur(3px); }\n.pm-forward-sheet.is-open{ display:flex; }\n.pm-forward-dialog{ width:min(100%,460px); max-height:min(68vh,520px); display:flex; flex-direction:column; overflow:hidden; border-radius:16px; background:var(--bg); color:var(--fg); box-shadow:0 18px 50px rgba(0,0,0,.22); }\n.pm-forward-head{ flex:none; display:flex; align-items:center; justify-content:space-between; padding:14px 16px 12px; border-bottom:1px solid rgba(127,127,127,.12); }\n.pm-forward-title{ font-size:16px; font-weight:650; }\n.pm-forward-close{ border:0; background:transparent; color:var(--fg); font:inherit; opacity:.7; padding:5px 2px; }\n.pm-forward-list{ overflow:auto; padding:8px 10px calc(8px + env(safe-area-inset-bottom,0px)); }\n.pm-forward-item{ width:100%; display:flex; align-items:center; gap:12px; padding:10px 8px; border:0; border-radius:10px; background:transparent; color:var(--fg); text-align:left; font:inherit; }\n.pm-forward-item:active{ background:rgba(127,127,127,.12); }\n.pm-forward-avatar{ width:38px; height:38px; flex:none; display:grid; place-items:center; overflow:hidden; border-radius:12px; background:linear-gradient(135deg, hsl(var(--deg,200) 60% 72%), hsl(calc(var(--deg,200) + 55) 55% 60%)); color:#111; font-weight:650; }\n.pm-forward-avatar img{ width:100%; height:100%; display:block; object-fit:cover; }\n.pm-forward-name{ min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }\n.pm-forward-empty{ padding:34px 14px; text-align:center; opacity:.58; font-size:13px; }\n'''
